// ---------- times ----------
const G2 = "guilford-2", G3 = "guilford-3", S3 = PS(G3);
const T_LEE = at(G2, "Henry Lee's cavalry"), T_QUAKER = at(G2, "at a Quaker meeting"), T_KNEW = at(G2, "so Greene knew"),
  T_CORN = at(G2, "And Cornwallis knew"), T_CAMDEN = at(G2, "At Camden"), T_THROWN = at(G2, "thrown away"), T_CHARGE = at(G2, "One hard charge"),
  T_ALONE = at(G2, "and the Continentals behind"), T_BEATEN = at(G2, "outnumbered and beaten");
const T_SAW = at(G3, "But Greene saw"), T_MORGAN = at(G3, "He took the idea Morgan"), T_DEEPER = at(G3, "and made it deeper"),
  T_THREE = at(G3, "Instead of one line"), T_YARDS = at(G3, "each a few hundred"), T_NC = at(G3, "The North Carolina militia"),
  T_VA = at(G3, "Behind them, in the trees"), T_RISE = at(G3, "And on the rise"), T_ASK = at(G3, "Greene didn't ask"),
  T_TWO = at(G3, "He asked them to fire"), T_FALL = at(G3, "and then fall back");
const T_HOLD = B.end(G3) + 0.3;   // archive paragraph after this: the map holds

// ---------- map layers ----------
B.image("assets/media/guilford_1781_ref.jpg", 0, 0, 2880, 1620, { t: 0, dur: 0.01 });
const LV = LivingK(B); LV.clouds({ n: 6, opacity: 0.14 }); LV.shimmer(GEO.streams, { color: "rgba(200,228,255,0.35)", width: 1.2 }); LV.scaleBar(3.86); LV.north();
const ROAD = GEO.road, REEDY = GEO.reedy, PL = GEO.places, CH = PL.courthouse;
const roadAt = (x) => [x, yOn(ROAD, x)];
const lblR = (txt, x, y, rot, t, until, size = 9, col = "#efe3c4") => GG.pin(`<div class="gg-lbl" style="position:relative;font-size:${size}px;color:${col};font-style:italic;letter-spacing:.16em;transform:rotate(${rot}deg);white-space:nowrap;text-shadow:0 1px 3px #000,0 0 6px #000">${txt}</div>`, x, y, { t, until });
const sideLbl = (txt, x, y, t, until, o = {}) => GG.pin(`<div class="gg-lbl" style="position:relative;font-size:${o.size || 6}px;color:${o.col || "#f7f3ea"};letter-spacing:.08em;white-space:nowrap;text-shadow:0 0.5px 1.5px #000,0 0 3px #000">${txt}</div>`, x, y, { t, until, anchor: o.right ? [-100, -50] : [0, -50] });

// ---------- camera ----------
const OV = [1410, 815];   // the whole battlefield
B.camera([[0, 900, 1040, 1.3], [T_QUAKER - 0.5, 910, 1030, 1.32], [T_KNEW + 0.5, 1020, 960, 1.4], [T_CORN - 0.2, 1120, 920, 1.55],
  [T_CORN + 2.2, 1290, 845, 2.7], [T_CAMDEN - 0.2, 1300, 845, 2.75], [T_CHARGE + 0.4, 1390, 825, 2.6], [T_BEATEN + 1.0, 1400, 820, 2.65],
  [T_SAW + 1.6, OV[0], OV[1], 3.0], [T_NC - 0.4, OV[0] - 10, OV[1] + 5, 3.05], [T_NC + 2.5, 1370, 830, 3.25], [T_VA + 2.0, 1420, 815, 3.2],
  [T_RISE + 2.4, 1470, 800, 3.1], [T_ASK, OV[0], OV[1], 3.0], [T_FALL + 1.2, 1390, 822, 3.15], [END, 1388, 822, 3.17]]);
B.showDate(0.1);
B.date("15 MARCH 1781", 0.2, null, 36);
legend(0.3, END + 1, true);
const flagPair = (t, until, w, us, gb) => { flag(FL.us, "UNITED STATES", ...us, t, until, w); flag(FL.gb, "GREAT BRITAIN", ...gb, t + 0.1, until, w); };
flagPair(0.2, T_CORN + 1.2, 88, [1500, 830], [330, 1010]);
flagPair(T_CORN + 1.4, T_SAW + 1.2, 44, [1560, 690], [1060, 760]);
flagPair(T_SAW + 1.4, END + 1, 38, [1690, 790], [1125, 728]);

// labels: places (small white boxes) + roads
lblR("GREAT SALISBURY ROAD", 930, 975, -27, 0.4, T_CORN + 1, 16);
lblR("GREAT SALISBURY ROAD", 1258, 828, -8, T_CORN + 1.2, END + 1, 6.5);
lblR("REEDY FORK ROAD", 1626, 640, 72, 0.5, END + 1, 7);
box("GUILFORD COURTHOUSE", CH[0] + 25, CH[1] - 31, 0.4, 7.5, END + 1, { sfx: false });
box("HOSKINS FARM", PL.hoskins[0] + 15, PL.hoskins[1] - 72, 0.5, 6, END + 1, { sfx: false, bg: "#e6dcc4" });
box("TO NEW GARDEN ↙", 420, 1170, 0.5, 14, T_CORN + 1, { sfx: false });

// ---------- guilford-2: dawn clash near New Garden ----------
const NGX = 640, NG = roadAt(NGX);
U("lee", "carth", [NG[0] + 26, NG[1] - 20], "infantry", null, { w: 40, h: 26, cav: true, t: T_LEE });
U("tar0", "rome", [NG[0] - 40, NG[1] + 30], "infantry", null, { w: 40, h: 26, cav: true, t: T_LEE + 0.4 });
sideLbl("LEE'S LEGION", NG[0] + 50, NG[1] - 20, T_LEE + 0.2, T_KNEW + 2, { size: 12 });
sideLbl("TARLETON'S DRAGOONS", NG[0] - 64, NG[1] + 30, T_LEE + 0.6, T_KNEW + 2, { size: 12, right: true });
badge({ name: "HENRY LEE", role: "LEE'S LEGION", initials: "", photo: PHOTO("lee"), flag: FL.us, side: "carth", corner: "bl", t: T_LEE - 0.2, until: T_KNEW + 1.4 });
badge({ name: "BANASTRE TARLETON", role: "BRITISH LEGION", initials: "", photo: PHOTO("tarleton"), flag: FL.gb, side: "rome", corner: "br", t: T_LEE + 0.3, until: T_KNEW + 1.4 });
mv("tar0", T_LEE + 1.6, 1.2, [NG[0] - 6, NG[1] + 8], "power2.in"); mv("lee", T_LEE + 1.6, 1.2, [NG[0] + 10, NG[1] - 6], "power2.in");
for (let k = 0; k < 7; k++) puff(NG[0] + ((k * 13) % 30) - 14, NG[1] + ((k * 7) % 22) - 10, T_LEE + 2.8 + k * 0.28, 5);
SFX("hit", T_LEE + 2.85); SFX("mg", T_LEE + 3.2);
K.smoke(NG[0], NG[1], T_LEE + 3.0, { n: 4, r: 18, rise: 30, life: 3.2, alpha: 0.55 });
box("DAWN: CLASH NEAR NEW GARDEN MEETING HOUSE", NG[0] + 60, NG[1] - 66, T_QUAKER - 0.2, 13, T_KNEW + 2.2, { bg: "#efe3c4" });
// Lee falls back to Greene; the British column comes up the road behind him
const ROAD_W = ROAD.filter((p) => p[0] >= NGX - 120 && p[0] <= 1190);
mvAlong("lee", ROAD.filter((p) => p[0] >= NGX && p[0] <= 1500), T_KNEW - 0.6, 4.0);
B.hideUnits(["lee"], T_CORN + 0.4);
mv("tar0", T_KNEW, 3.6, roadAt(900), "power1.inOut"); B.hideUnits(["tar0"], T_CORN + 0.6);
arw({ pts: [ROAD_W[0], ...ROAD_W.filter((_, i) => i % 3 === 0).slice(1), ROAD_W[ROAD_W.length - 1]], side: "rome", t: T_KNEW, dur: 2.6, width: 9, until: T_CORN + 2.2 });
K.target(1200, 845, T_KNEW + 1.8, { r: 34, side: "#ffd54a", until: T_CORN + 1.6 });
B.caption("GREENE KNEW WHERE THE BRITISH WERE COMING FROM", T_KNEW + 0.6, T_CORN - 0.1, "carth");

// ---------- the British deploy at the Hoskins farm ----------
const BR = [  // id, x, y, icon, label, label side (1 = east of the counter, -1 = west)
  ["jag", 1201, 763, "infantry", "JÄGERS · GUARDS LIGHT INF.", 1], ["b33", 1203, 789, "infantry", "33RD", 1], ["b23", 1205, 814, "infantry", "23RD ROYAL WELCH FUS.", 1],
  ["ra", 1197, 845, "artillery", "ROYAL ARTILLERY", 1], ["b71", 1207, 870, "infantry", "71ST HIGHLANDERS", 1], ["bose", 1209, 896, "infantry", "VON BOSE (HESSIANS)", 1],
  ["g2", 1176, 806, "infantry", "2ND GUARDS · GRENADIERS", -1], ["g1", 1178, 905, "infantry", "1ST GUARDS", -1], ["tarl", 1138, 860, "cav", "TARLETON'S LEGION", -1]];
const T_DEP = T_CORN + 0.9;
BR.forEach(([id, x, y, icon, lab, sd], k) => {
  U(id, "rome", [x, y], icon === "cav" ? "infantry" : icon, null, { w: icon === "cav" ? 24 : 20, h: icon === "cav" ? 16 : 14, cav: icon === "cav", t: T_DEP + k * 0.16 });
  sideLbl(lab, x + sd * 14, y, T_DEP + 0.3 + k * 0.16, T_CAMDEN - 0.2, { size: 6, right: sd < 0 });
});
const RF0 = K.front({ pts: [[1217, 752], [1219, 800], [1215, 845], [1219, 885], [1222, 912]], sideA: "rome", sideB: "rome", t: T_DEP + 0.4, dur: 1.4, width: 15, until: END + 1 });
const CB = badge({ name: "LORD CORNWALLIS", role: "BRITISH COMMANDER", initials: "", photo: PHOTO("cornwallis"), flag: FL.gb, side: "rome", corner: "br", t: T_CORN - 0.1, until: T_ALONE + 1.0 });
ticker("BRITISH", 2000, "~", "", "right:70px;top:300px;", T_CORN + 1.6, 1.4, T_CAMDEN + 0.6, 8, { col: "#e3232f", size: 46 });

// ---------- the ghost of Camden (what militia did there) ----------
const GH = [[1338, 800], [1340, 822], [1342, 856], [1340, 880]];
const ghosts = GH.map((p, k) => ghost(p[0], p[1], T_CAMDEN + k * 0.12, T_THROWN + 2.6, 20, 14, ""));
box("CAMDEN · AUGUST 1780", 1342, 772, T_CAMDEN + 0.1, 7, T_THROWN + 2.6, { bg: "#d6cfbd" });
ghosts.forEach((g, k) => B.tl.to(g, { x: 60 + k * 14, y: (k - 1.5) * 16, rotation: (k % 2 ? 50 : -40), duration: 1.8, ease: "power2.in" }, T_THROWN + 0.4 + k * 0.1));
for (let k = 0; k < 4; k++) { const q = GH[k]; GG.pin(`<svg width="14" height="4" viewBox="0 0 14 4"><path d="M0 2 L12 2 M11 0.5 L13.5 2 L11 3.5" stroke="#d6cfbd" stroke-width="1.2" fill="none"/></svg>`, q[0] - 4, q[1] + 6, { t: T_THROWN + 0.5 + k * 0.1, until: T_THROWN + 2.6 }); }
B.caption("CAMDEN: THE MILITIA THREW AWAY THEIR MUSKETS AND RAN", T_CAMDEN + 0.4, T_CHARGE - 0.1, "rome");
SFX("ref:pop", T_CAMDEN + 0.1);

// ---------- what Cornwallis believed ----------
belief("WHAT CORNWALLIS BELIEVED", "THE MILITIA WILL RUN", T_CHARGE, S3 - 0.2);
arw({ pts: [[1222, 832], [1330, 828], [1450, 812], [1560, 778]], side: "rome", t: T_CHARGE + 0.4, dur: 1.6, width: 12, until: S3 + 0.4 });
box("ONE HARD CHARGE", 1395, 860, T_CHARGE + 1.0, 8, S3 + 0.4, { bg: "#ffd9d2" });
const GC = [[1588, 722], [1590, 748], [1592, 772], [1594, 796]].map((p, k) => ghost(p[0], p[1], T_ALONE + k * 0.12, S3 + 0.4, 20, 14, ""));
box("CONTINENTALS · LEFT ALONE", 1592, 832, T_ALONE + 0.2, 7, S3 + 0.4, { bg: "#d6cfbd" });
[[[1530, 690], [1570, 712]], [[1535, 840], [1575, 812]]].forEach((p, k) => arw({ pts: p, side: "rome", t: T_BEATEN - 0.6 + k * 0.2, dur: 0.7, width: 6, until: S3 + 0.4 }));
GG.stamp("OUTNUMBERED AND BEATEN", T_BEATEN, S3 + 0.2, { size: 40, top: 860 });

// ============ guilford-3: Greene's three lines ============
badge({ name: "NATHANAEL GREENE", role: "SAW SOMETHING DIFFERENT", initials: "", photo: PHOTO("greene"), flag: FL.us, side: "carth", corner: "br", t: T_SAW - 0.1, until: T_THREE + 0.2 });
badge({ name: "DANIEL MORGAN", role: "COWPENS · JANUARY 1781", initials: "", photo: PHOTO("morgan"), flag: FL.us, side: "carth", corner: "bl", t: T_MORGAN - 0.1, until: T_THREE + 0.4 });
B.caption("MORGAN'S COWPENS IDEA, MADE DEEPER", T_DEEPER - 0.2, T_THREE + 1.6, "carth");
// 1 · 2 · 3 markers, then the ~400-yard brackets
